export function ActivityFeed({
  heading = "{{heading}}",
  entries = "{{entries}}",
  avatarShape = "{{avatarShape}}",
  accent = "{{accent}}",
  showTimestamps = {{showTimestamps}},
}) {
  const items = [
    { initials: "PS", name: "Priya Shah", action: "starred", object: "atlas-ui", time: "2026-08-18T09:42:00Z", label: "2 minutes ago" },
    { initials: "TR", name: "Tomás Rivera", action: "commented on", object: "Q3 roadmap", time: "2026-08-18T09:24:00Z", label: "18 minutes ago" },
    { initials: "AB", name: "Aisha Bello", action: "uploaded 3 files to", object: "Brand assets", time: "2026-08-18T08:38:00Z", label: "1 hour ago" },
    { initials: "JL", name: "Jordan Lee", action: "followed you", object: null, time: "2026-08-18T06:10:00Z", label: "3 hours ago" },
    { initials: "SO", name: "Sam Okafor", action: "closed issue", object: "Fix pagination bug", time: "2026-08-17T18:05:00Z", label: "yesterday" },
  ].slice(0, Number(entries));
  return (
    <section style={{ fontFamily: "system-ui, sans-serif", fontSize: 14, lineHeight: 1.5, color: "#241430", background: "#FAF7F2", padding: 18, borderRadius: 12, maxWidth: 380, boxSizing: "border-box" }}>
      <h3 style={{ margin: "0 0 12px", fontSize: 15, fontWeight: 600 }}>{heading}</h3>
      <ol style={{ listStyle: "none", margin: 0, padding: 0, display: "flex", flexDirection: "column", gap: 14 }}>
        {items.map((item) => (
          <li key={item.initials} style={{ display: "flex", gap: 10, alignItems: "flex-start" }}>
            <span aria-hidden="true" style={{ flex: "none", width: 30, height: 30, display: "grid", placeItems: "center", fontSize: 11, fontWeight: 700, color: "#241430", background: accent, borderRadius: avatarShape === "circle" ? "50%" : 6 }}>{item.initials}</span>
            <div style={{ minWidth: 0 }}>
              <p style={{ margin: 0, fontSize: 13.5 }}>
                <strong>{item.name}</strong> {item.action}
                {item.object ? <> <span style={{ fontWeight: 600 }}>{item.object}</span></> : null}
              </p>
              {showTimestamps && (
                <time dateTime={item.time} style={{ display: "block", marginTop: 2, fontSize: 12, color: "#24143099" }}>{item.label}</time>
              )}
            </div>
          </li>
        ))}
      </ol>
    </section>
  );
}
